// 1. Green ON (Red/Yellow OFF) for 4s
// 2. Yellow ON (Green/Red OFF) for 1.5s
// 3. Red ON (Green/Yellow OFF) for 4s
// 4. Repeat

codeExamples.code:
const int RED = 10, YELLOW = 9, GREEN = 8;

void setup() {
  pinMode(RED, OUTPUT); pinMode(YELLOW, OUTPUT); pinMode(GREEN, OUTPUT);
}

void loop() {
  digitalWrite(GREEN, HIGH); digitalWrite(YELLOW, LOW); digitalWrite(RED, LOW);
  delay(4000);
  digitalWrite(GREEN, LOW); digitalWrite(YELLOW, HIGH);
  delay(1500);
  digitalWrite(YELLOW, LOW); digitalWrite(RED, HIGH);
  delay(4000);
}

