// DESIGN: Sound buzzer when safety button is pressed
// INPUT: BTN_PIN (2, INPUT_PULLUP)
// OUTPUT: BUZZER_PIN (6), LED_PIN (8)
const int BTN_PIN = 2;
const int BUZZER_PIN = 6;
const int LED_PIN = 8;

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  bool triggered = (digitalRead(BTN_PIN) == LOW);
  digitalWrite(LED_PIN, triggered ? HIGH : LOW);
  if (triggered) tone(BUZZER_PIN, 1000);
  else noTone(BUZZER_PIN);
}

